-- ============================================================================
-- Orange Taxi — production catch-up (GENERATED by scripts/catch-up/build.mjs; do not edit by hand)
--
-- The live project's schema (dumped 2026-10-25) never received most repo migrations: it has 11
-- tables, no integrity triggers, and permissive "Allow all" policies. This file replays those
-- migrations in order, made idempotent for the live schema, then removes the leftover live-only
-- policies. Apply it, then every migration from 20261025120000 on, in ONE transaction:
--
--   psql "$DB_URL" --single-transaction -v ON_ERROR_STOP=1 \
--     -f supabase/catch-up/production_catch_up.sql \
--     -f supabase/migrations/20261025120000_audit_remediation.sql \
--     -f supabase/migrations/20261025130000_audit_remediation_2.sql \
--     -f supabase/migrations/20261025140000_account_deletion_anonymize.sql \
--     -f supabase/migrations/20261025150000_admin_pricing_and_cancellation.sql
--
-- Does not change vehicle categories, prices, bookings or users. Data it does write: existing drivers
-- get status = 'active' (new column) and a geohash backfill.
-- Verified by scripts/db-tests (CATCHUP=1) against the dumped live schema plus fixture rows.
-- ============================================================================
-- Backfills run as the trusted service role so the integrity triggers this file installs allow them.
SELECT set_config('request.jwt.claim.role', 'service_role', true);
SET LOCAL search_path = public, extensions;

-- ======================================================================
-- Live-schema prelude: columns the repo's base schema had and the live tables don't
-- ======================================================================
-- drivers: the live table tracks approval with is_active/is_verified; the apps use status.
ALTER TABLE public.drivers ADD COLUMN IF NOT EXISTS vehicle_code text NOT NULL DEFAULT 'ORANGE_SEDAN';
ALTER TABLE public.drivers ADD COLUMN IF NOT EXISTS status text;
-- On 2026-10-25 every live driver had is_active = false and is_verified = false, yet drivers were
-- online and completing rides: neither flag gated anything. Keep everyone able to work as today;
-- admins deactivate individual drivers from the admin panel (status = 'inactive').
UPDATE public.drivers SET status = 'active' WHERE status IS NULL;
ALTER TABLE public.drivers ALTER COLUMN status SET DEFAULT 'active';
ALTER TABLE public.drivers ALTER COLUMN status SET NOT NULL;
-- Admin-created drivers exist before their login is linked (admin_link_driver).
ALTER TABLE public.drivers ALTER COLUMN user_id DROP NOT NULL;
-- Columns the repo's base schema has and the live pricing/vehicle tables lack (the base-schema
-- updated_at trigger on vehicle_categories needs updated_at; the admin pricing page needs the rest).
ALTER TABLE public.pricing_settings ADD COLUMN IF NOT EXISTS waiting_charge_per_min numeric NOT NULL DEFAULT 2;
ALTER TABLE public.pricing_settings ADD COLUMN IF NOT EXISTS waiting_free_minutes integer NOT NULL DEFAULT 3;
ALTER TABLE public.pricing_settings ADD COLUMN IF NOT EXISTS cancellation_charge numeric NOT NULL DEFAULT 50;
ALTER TABLE public.pricing_settings ADD COLUMN IF NOT EXISTS surge_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.pricing_settings ADD COLUMN IF NOT EXISTS currency text NOT NULL DEFAULT 'INR';
ALTER TABLE public.vehicle_categories ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.user_roles ADD COLUMN IF NOT EXISTS id uuid NOT NULL DEFAULT gen_random_uuid();
